using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
public class MachineScanResult {
 public long Files,Directories,Bytes,Skipped,LargeCount;public bool Cancelled;
 public List<string> Roots=new List<string>();public List<FileItem> Large=new List<FileItem>();public TimeSpan Duration;
 public string Report(){return (Cancelled?"Đã dừng · kết quả một phần":"Đã duyệt xong phạm vi có thể truy cập")+"\nỔ/thư mục: "+String.Join(", ",Roots)+"\n"+Files.ToString("N0")+" tệp · "+Directories.ToString("N0")+" thư mục · "+Features.Size(Bytes)+" dung lượng tệp ghi nhận\n"+LargeCount.ToString("N0")+" tệp từ 100 MB · hiển thị tối đa 1.000 tệp lớn nhất\n"+Skipped.ToString("N0")+" mục/thư mục bỏ qua: không có quyền, liên kết, lỗi đọc hoặc khu vực loại trừ\nThời gian: "+Duration.ToString(@"hh\:mm\:ss")+"\nĐọc thông tin tệp, không đọc toàn bộ nội dung, không quét virus. Không duyệt ổ mạng/USB, liên kết, Thùng rác và System Volume Information. Dung lượng logic có thể tính cả hard link; không phải dung lượng có thể dọn.";}
}
static class WholeMachine {
 public static MachineScanResult Scan(IEnumerable<string> roots,CancellationToken token,IProgress<string> progress){var result=new MachineScanResult();var clock=Stopwatch.StartNew();long last=0;foreach(string root in roots.Distinct(StringComparer.OrdinalIgnoreCase)){if(token.IsCancellationRequested)break;result.Roots.Add(root);var stack=new Stack<string>();stack.Push(root);while(stack.Count>0&&!token.IsCancellationRequested){string dir=stack.Pop();try{if(!Features.NoLinks(dir)){result.Skipped++;continue;}result.Directories++;foreach(string path in Directory.EnumerateFileSystemEntries(dir)){if(token.IsCancellationRequested)break;try{var attr=File.GetAttributes(path);if((attr&FileAttributes.ReparsePoint)!=0){result.Skipped++;continue;}if((attr&FileAttributes.Directory)!=0){string name=Path.GetFileName(path);if(name.Equals("$RECYCLE.BIN",StringComparison.OrdinalIgnoreCase)||name.Equals("System Volume Information",StringComparison.OrdinalIgnoreCase)){result.Skipped++;continue;}stack.Push(path);}else{var file=new FileInfo(path);long size=file.Length;result.Files++;result.Bytes+=size;if(size>=100L*1024*1024){result.LargeCount++;result.Large.Add(new FileItem{Path=path,Size=size,Modified=file.LastWriteTimeUtc});if(result.Large.Count>=2000)result.Large=result.Large.OrderByDescending(x=>x.Size).Take(1000).ToList();}}}catch(UnauthorizedAccessException){result.Skipped++;}catch(IOException){result.Skipped++;}if(clock.ElapsedMilliseconds-last>=250){last=clock.ElapsedMilliseconds;if(progress!=null)progress.Report("Đang đọc "+root+" · "+clock.Elapsed.ToString(@"hh\:mm\:ss")+"\n"+result.Files.ToString("N0")+" tệp · "+result.Directories.ToString("N0")+" thư mục · bỏ qua "+result.Skipped.ToString("N0")+"\n"+path);}}}catch(UnauthorizedAccessException){result.Skipped++;}catch(IOException){result.Skipped++;}}}result.Cancelled=token.IsCancellationRequested;result.Duration=clock.Elapsed;result.Large=result.Large.OrderByDescending(x=>x.Size).Take(1000).ToList();return result;}
 public static IEnumerable<string> LocalDrives(){return DriveInfo.GetDrives().Where(x=>x.DriveType==DriveType.Fixed&&x.IsReady).Select(x=>x.RootDirectory.FullName).ToArray();}
 static int KeeperPenalty(FileItem f){string p=(f.Path??"").ToLowerInvariant();int s=0;if(p.Contains("download")||p.Contains("tải về"))s+=10;if(p.Contains("temp")||p.Contains("tạm"))s+=10;if(p.Contains("copy")||p.Contains("bản sao")||p.Contains(" (1)")||p.Contains(" (2)"))s+=5;return s;}
 public static int SelectDuplicateExtras(IList<FileItem> files){foreach(var file in files)file.Selected=false;foreach(var group in files.GroupBy(x=>x.Group)){var candidates=group.Where(x=>!FileActions.ProtectedPath(x.Path)).OrderBy(KeeperPenalty).ThenBy(x=>x.Path.Length).ThenBy(x=>x.Path,StringComparer.OrdinalIgnoreCase).ToList();foreach(var file in candidates.Skip(1))file.Selected=true;}return files.Count(x=>x.Selected);}
}

class MachineAuditProgress:IProgress<string>{readonly string path;public MachineAuditProgress(string value){path=value;}public void Report(string text){File.WriteAllText(path,text);}}
